<script setup lang="ts">
import {computed,onBeforeUnmount,reactive,ref,watch} from 'vue';
import {request,session} from '../api';
import type {OrderView} from '@quote/contracts';
import {chooseSourceFiles,createMiniSourceAssets,openMiniSource,sourceDescriptorStorage} from '../source-files';
import {SourceOperations,fileMeta,formatBeijingTimestamp,type SourceFile,type SourceReference,type SpreadsheetFieldMapping} from '../../../../packages/source-client/src';
import {SourceController,createSourceState} from '../../../../packages/source-client/src/controller';
const props=defineProps<{reference:SourceReference;userId?:string;readonly?:boolean;locked?:boolean;mode?:'image'|'excel';orderVersion?:number}>(),emit=defineEmits<{(e:'changed'):void;(e:'busy-changed',v:boolean):void;(e:'failure',v:unknown):void}>();
const state=reactive(createSourceState()),localBusy=ref(false),error=ref(''),ready=ref(false),tab=ref<'raw'|'mapped'>('raw'),rawPage=ref(1),mappedPage=ref(1);let controller:SourceController<Blob|string>|null=null,epoch=0,deferredChanged=false;
const locked=computed(()=>!!props.locked||state.busy||localBusy.value||!!state.pending),rawPages=computed(()=>Math.max(1,Math.ceil((state.job?.rawRows?.length||0)/25))),mappedPages=computed(()=>Math.max(1,Math.ceil((state.preview?.rows.length||0)/25))),rawRows=computed(()=>state.job?.rawRows?.slice((rawPage.value-1)*25,rawPage.value*25)||[]),mappedRows=computed(()=>state.preview?.rows.slice((mappedPage.value-1)*25,mappedPage.value*25)||[]),maxColumns=computed(()=>Math.max(1,...(state.job?.rawRows||[]).map(r=>r.cells.length))),tableWidth=computed(()=>(maxColumns.value*220+500)+'rpx');
const fields:{key:keyof SpreadsheetFieldMapping['columns'];label:string;required?:boolean}[]=[{key:'name',label:'品名',required:true},{key:'quantity',label:'数量',required:true},{key:'spec',label:'规格'},{key:'unit',label:'单位'},{key:'remark',label:'备注'},{key:'sourcePrice',label:'来源参考价'}],isImage=(f:SourceFile)=>['jpg','jpeg','png'].includes(f.fileType),parseAllowed=(f:SourceFile)=>['purchase_image','purchase_excel','manufacturer_source'].includes(f.purpose);
function fail(e:unknown){error.value=e instanceof Error?e.message:'原文件操作失败，请重试。';if([401,403,404,410].includes((e as {status?:number})?.status||0)){state.files=[];state.job=null;state.preview=null;}emit('failure',e);}
async function version(){let value=props.orderVersion;if(value===undefined){if(props.reference.kind!=='purchase_revision')throw new Error('当前资料不属于采购草稿。');const path=session.value?.user.role==='hospital'?'/hospital/purchase-orders/':'/sales/purchase-orders/';value=(await request<Pick<OrderView,'version'>>(path+props.reference.orderId)).version;}if(!Number.isSafeInteger(value)||value<=0)throw new Error('当前订单版本无效，请重新加载采购草稿。');return value;}
function setup(){epoch++;controller?.dispose();localBusy.value=false;deferredChanged=false;error.value='';ready.value=false;rawPage.value=1;mappedPage.value=1;try{const userId=props.userId||session.value?.user.id;if(!userId)throw new Error('请先登录后查看原始资料。');const currentEpoch=epoch,sessionUserId=session.value?.user.id,token=session.value?.token,propUserId=props.userId,reference=JSON.stringify(props.reference);const current=()=>currentEpoch===epoch&&session.value?.user.id===sessionUserId&&session.value?.token===token&&props.userId===propUserId&&JSON.stringify(props.reference)===reference;const operations=new SourceOperations<Blob|string>(userId,p=>request(p),(p,b,k)=>request(p,'POST',b as Record<string,unknown>,k),sourceDescriptorStorage,createMiniSourceAssets(),()=> 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g,c=>{const r=Math.floor(Math.random()*16);return(c==='x'?r:(r&3)|8).toString(16);}),current);controller=new SourceController(props.reference,p=>request(p),(p,b)=>request(p,'POST',b as Record<string,unknown>),operations,sourceDescriptorStorage,state,{readonly:()=>!!props.readonly||!!props.locked,version,changed:()=>{if(localBusy.value)deferredChanged=true;else emit('changed');},busy:v=>emit('busy-changed',v||localBusy.value),failure:fail});ready.value=true;void controller.refresh();}catch(e){controller=null;fail(e);}}
watch(()=>JSON.stringify([props.reference,props.userId,session.value?.user.id,session.value?.token]),setup,{immediate:true});watch(()=>state.job?.id,()=>{rawPage.value=1;mappedPage.value=1;tab.value='raw';});
async function upload(images:boolean,parent?:SourceFile){if(props.readonly||locked.value)return;const current=epoch;localBusy.value=true;emit('busy-changed',true);error.value='';try{const selected=await chooseSourceFiles(images);if(current!==epoch)return;for(const f of selected){fileMeta(f.name,f.size,props.reference);await controller?.upload({name:f.name,mime:f.mime,size:f.size},f.asset,parent?.id);if(state.error||state.pending||current!==epoch)break;}}catch(e){if(current===epoch)fail(e);}finally{if(current===epoch){localBusy.value=false;emit('busy-changed',!!state.pending);if(deferredChanged){deferredChanged=false;emit('changed');}}}}
async function open(file:SourceFile,download=false){if(locked.value)return;const currentEpoch=epoch,userId=session.value?.user.id,token=session.value?.token||'',propUserId=props.userId,reference=JSON.stringify(props.reference);const current=()=>currentEpoch===epoch&&session.value?.user.id===userId&&session.value?.token===token&&props.userId===propUserId&&JSON.stringify(props.reference)===reference;localBusy.value=true;emit('busy-changed',true);error.value='';try{const ticket=await request<{url:string;expiresAt:string}>('/files/'+encodeURIComponent(file.id)+'/download-url','POST',{});if(!current())return;await openMiniSource(ticket.url,token,file,download,current);}catch(e){if(current())fail(e);}finally{if(current()){localBusy.value=false;emit('busy-changed',!!state.pending);}}}
function ranges(required=false){return [...(required?[]:['不映射']),...Array.from({length:maxColumns.value},(_,i)=>'第 '+(i+1)+' 列')];}
function index(field:keyof SpreadsheetFieldMapping['columns'],required=false){return state.mapping.columns[field]===undefined?0:state.mapping.columns[field]!+(required?0:1);}
function mappedLabel(field:keyof SpreadsheetFieldMapping['columns']){const i=state.mapping.columns[field];return i===undefined?(field==='unit'?'未映射，按 kg 校对':'不映射'):'第 '+(i+1)+' 列';}
function column(field:keyof SpreadsheetFieldMapping['columns'],required:boolean|undefined,e:unknown){const i=Number((e as {detail:{value:string}}).detail.value);controller?.setColumn(field,!required&&i===0?'':String(i-(required?0:1)));mappedPage.value=1;}
function header(e:unknown){controller?.invalidatePreview();state.mapping.headerRow=Number((e as {detail:{value:string}}).detail.value);}
async function preview(){await controller?.preview();if(state.preview){tab.value='mapped';mappedPage.value=1;}}
defineExpose({refresh:()=>controller?.refresh(),canLeave:()=>!localBusy.value&&(controller?.canLeave()??true),pendingTarget:()=>state.pending?.reference||null,parsedJob:computed(()=>state.job?Object.freeze({...state.job}):null),sourceFiles:computed(()=>Object.freeze(state.files.map(f=>Object.freeze({...f,reference:Object.freeze({...f.reference})})))),check:()=>controller?.check(),retry:()=>controller?.retryPending()});
onBeforeUnmount(()=>{epoch++;controller?.dispose();emit('busy-changed',false);});
</script>
<template>
 <view class="source-files">
  <view class="heading"><text class="title">原始资料</text><button size="mini" :disabled="locked||!ready" @click="controller?.refresh()">刷新</button></view><text class="help">每个文件不超过 20MB；采购图片每单最多 20 张。原单与采购明细分别保留。</text>
  <text v-if="readonly" class="notice">当前资料只读，可查看原图和下载原件。</text>
  <view v-else class="actions"><button v-if="reference.kind!=='manufacturer'&&mode!=='excel'" :disabled="locked||!ready" @click="upload(true)">拍照 / 相册图片</button><button v-if="reference.kind!=='template'&&mode!=='image'" :disabled="locked||!ready" @click="upload(false)">Excel / CSV</button></view>
  <view v-if="state.pending" class="warning"><text class="strong">上次原单操作结果待核实</text><text class="help">{{state.pending.action==='upload'?state.pending.body.fileName:'解析或候选应用'}} · 原文件与原请求标识已保留。</text><view class="actions"><button :disabled="state.busy||localBusy" @click="controller?.check()">核对原操作</button><button :disabled="state.busy||localBusy" @click="controller?.retryPending()">原请求重试</button></view></view>
  <text v-if="state.error||error" class="error">{{state.error||error}}</text><text v-if="state.notice" class="notice">{{state.notice}}</text><text v-if="state.busy||localBusy" class="help">正在处理，请稍候…</text>
  <view v-for="file in state.files" :key="file.id" class="file"><text class="strong">{{file.fileName}}</text><text class="help">{{(file.byteSize/1024).toFixed(1)}} KB · {{formatBeijingTimestamp(file.createdAt)}}{{file.parentFileId?' · 更正版，原件保留':''}}</text><view class="actions"><button size="mini" :disabled="locked" @click="open(file)">{{isImage(file)?'查看原图':'下载原表'}}</button><button v-if="isImage(file)" size="mini" :disabled="locked" @click="open(file,true)">下载</button><button size="mini" :disabled="locked" @click="controller?.openJob(file)">解析记录</button><template v-if="!readonly"><button v-if="parseAllowed(file)" size="mini" :disabled="locked" @click="controller?.parse(file)">{{isImage(file)?'识别表格':'解析表格'}}</button><button size="mini" :disabled="locked" @click="upload(isImage(file),file)">上传更正版</button></template></view></view>
  <text v-if="!state.files.length&&!state.busy" class="empty">暂无原始资料</text>
  <view v-if="state.job" class="parse"><view class="heading"><text class="title">解析校对</text><button size="mini" :disabled="locked" @click="controller?.refreshJob()">刷新状态</button></view><text class="help">{{({pending:'等待解析',processing:'解析中',succeeded:'解析完成，待人工校对',failed:'解析失败'})[state.job.status]}} · 已尝试 {{state.job.attempts}} 次</text><text class="help">{{state.job.parserType==='ocr'?`置信度：${state.job.confidence===null?'未知':(state.job.confidence*100).toFixed(1)+'%'}`:'第一张工作表，最多1000数据行、64列'}}。候选不会自动勾选或冻结。</text>
   <view v-if="state.job.status==='failed'" class="warning"><text class="strong">{{state.job.errorCode}}</text><text class="help">{{state.job.errorMessage}}。原文件已保留，也可返回采购明细手工录入。</text><template v-if="!readonly&&state.job.retryable"><view v-if="state.job.resultUnknown" class="ack" @click="!locked&&(state.unknownAcknowledged=!state.unknownAcknowledged)"><checkbox :checked="state.unknownAcknowledged" :disabled="locked"/><text>我已人工核对上次识别结果未知，明确再次识别</text></view><button :disabled="locked||state.job.resultUnknown&&!state.unknownAcknowledged" @click="controller?.retryJob()">手动重试解析</button></template></view>
   <template v-if="state.job.rawRows"><view class="tabs"><button :class="{active:tab==='raw'}" @click="tab='raw'">原始单元格</button><button v-if="reference.kind!=='manufacturer'" :class="{active:tab==='mapped'}" @click="tab='mapped'">字段映射与候选</button></view>
    <template v-if="tab==='raw'"><text class="help">左右滑动查看原文；公式、链接与合并问题逐行保留。</text><scroll-view scroll-x class="table-scroll"><view class="raw-table" :style="{width:tableWidth}"><view class="table-row table-header"><text class="row-number">原行</text><text v-for="n in maxColumns" :key="n" class="cell">第 {{n}} 列</text><text class="cell">原文问题</text></view><view v-for="row in rawRows" :key="row.rowNumber" class="table-row"><text class="row-number">{{row.rowNumber}}</text><text v-for="n in maxColumns" :key="n" class="cell">{{row.cells[n-1]||'—'}}</text><text class="cell error">{{row.errors.join('；')||'—'}}</text></view></view></scroll-view><view class="pagination"><button size="mini" :disabled="rawPage<=1" @click="rawPage--">上一页</button><text>{{rawPage}} / {{rawPages}}</text><button size="mini" :disabled="rawPage>=rawPages" @click="rawPage++">下一页</button></view></template>
    <template v-else-if="reference.kind!=='manufacturer'"><label class="mapping-row"><text>表头行号（0 无表头）</text><input type="number" :value="String(state.mapping.headerRow)" :disabled="locked" @input="header"/></label><view v-for="field in fields" :key="field.key" class="mapping-row"><text>{{field.label}}{{field.required?' *':''}}</text><picker :range="ranges(field.required)" :value="index(field.key,field.required)" :disabled="locked" @change="column(field.key,field.required,$event)"><view class="picker">{{mappedLabel(field.key)}} ›</view></picker></view><button :disabled="locked" @click="preview">预览字段映射</button><text class="help">单位须人工核对为 kg；未映射单位时按 kg 校对。来源参考价仅供查询，不参与计价。</text>
     <template v-if="state.preview"><text class="help">有效 {{state.preview.validRows}} 行 / 有问题 {{state.preview.invalidRows}} 行</text><view v-for="row in mappedRows" :key="row.rowNumber" class="candidate"><view class="heading"><text class="strong">第 {{row.rowNumber}} 行 · {{row.name||'品名无效'}}</text><checkbox v-if="!readonly&&reference.kind==='purchase_revision'" :checked="state.selectedRows.includes(row.rowNumber)" :disabled="locked||!!row.errors.length||state.job.applied" @click="controller?.toggleRow(row.rowNumber,!state.selectedRows.includes(row.rowNumber))"/></view><text class="help">{{row.spec||'未填规格'}} · {{row.quantity||'数量无效'}} {{row.unit}}</text><text class="help">备注 {{row.remark||'—'}} · 参考价 {{row.sourcePrice||'—'}}</text><text :class="row.errors.length?'error':'help'">{{row.errors.join('；')||'待人工核对'}}</text></view><view class="pagination"><button size="mini" :disabled="mappedPage<=1" @click="mappedPage--">上一页</button><text>{{mappedPage}} / {{mappedPages}}</text><button size="mini" :disabled="mappedPage>=mappedPages" @click="mappedPage++">下一页</button></view><template v-if="!readonly&&reference.kind==='purchase_revision'"><text class="help">选中行追加到草稿，全部仍待逐行校对；采购明细最多 200 行。</text><button class="primary" :disabled="locked||!state.selectedRows.length||state.job.applied" @click="controller?.apply()">{{state.job.applied?'已加入采购草稿':`加入选中 ${state.selectedRows.length} 行`}}</button></template></template>
    </template>
   </template>
  </view>
 </view>
</template>
<style scoped>
.source-files{min-width:0;padding:24rpx 0;color:#253e31}.heading{display:flex;align-items:center;justify-content:space-between;gap:15rpx}.title{font-size:29rpx;font-weight:650}.help,.notice,.error,.empty,.strong{display:block}.help{font-size:23rpx;color:#6d7b70;line-height:1.7;margin:10rpx 0;overflow-wrap:anywhere}.strong{font-size:25rpx;line-height:1.6;overflow-wrap:anywhere}.actions{display:flex;gap:10rpx;flex-wrap:wrap;margin:18rpx 0}.actions button{margin:0;font-size:23rpx;line-height:1.5;padding:15rpx}.file{border-bottom:1rpx solid #dce4d9;padding:22rpx 0}.file .actions{margin-bottom:0}.source-files button{border-radius:8rpx;background:#fff;color:#28543c;border:1rpx solid #cedbcd;font-size:24rpx}.source-files button:disabled{opacity:.48}.source-files button::after{border:0}.warning{padding:24rpx;background:#fff7e7;border:1rpx solid #ead5aa;border-radius:8rpx;margin:20rpx 0}.notice{background:#ecf3e9;padding:19rpx;font-size:24rpx;line-height:1.7;margin:18rpx 0}.error{font-size:23rpx;color:#a14535;line-height:1.7;margin:14rpx 0}.empty{font-size:24rpx;color:#8b978b;text-align:center;padding:35rpx}.parse{border-top:1rpx solid #d8e2d4;margin-top:25rpx;padding-top:25rpx}.ack{display:flex;gap:13rpx;font-size:24rpx;line-height:1.7;margin:20rpx 0}.tabs{display:flex;gap:12rpx;margin:25rpx 0}.tabs button{flex:1;margin:0}.tabs button.active{background:#e5efe1;border-color:#5d8b64}.table-scroll{width:100%;max-height:780rpx;border:1rpx solid #dae4d5;margin:15rpx 0}.table-row{display:flex;border-bottom:1rpx solid #e2e9dd;align-items:stretch}.table-header{background:#edf3e8}.cell{width:220rpx;flex-shrink:0;font-size:23rpx;padding:18rpx 14rpx;box-sizing:border-box;white-space:pre-wrap;overflow-wrap:anywhere;line-height:1.6}.row-number{width:95rpx;flex-shrink:0;padding:18rpx 10rpx;font-size:23rpx;box-sizing:border-box}.pagination{display:flex;align-items:center;justify-content:space-between;font-size:23rpx;margin:20rpx 0}.pagination button{margin:0}.mapping-row{display:flex;justify-content:space-between;gap:24rpx;align-items:center;padding:18rpx 0;border-bottom:1rpx solid #e0e8db;font-size:24rpx}.mapping-row input{width:130rpx;text-align:right;border:1rpx solid #d1dfc9;padding:12rpx}.picker{color:#2b6646;min-width:180rpx;text-align:right}.candidate{padding:20rpx;background:#f7f9f3;border-bottom:1rpx solid #dce5d6;margin-top:16rpx}.primary{background:#285b42!important;color:#fff!important}
</style>
